package org.eclipse.rdf4j.sail.lmdb.estimation;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;

class QuadSynopsisPersistenceBatchingTest {

	@Test
	void streamingWriterForwardsBuffersWithoutChangingPayload(@TempDir(cleanup = CleanupMode.NEVER) Path directory)
			throws Exception {
		QuadSynopsisBudget budget = QuadSynopsisBudget.create(1024L * 1024L, 8);
		QuadSnapshotIdentity identity = new QuadSnapshotIdentity(101L, 202L, 9L);
		QuadSynopsisBuilder builder = new QuadSynopsisBuilder(budget, identity, 44L);
		builder.add(1L, 2L, 3L, 4L);
		QuadSynopsisSnapshot snapshot = builder.build();
		CountingOutputStream destination = new CountingOutputStream();
		byte[] fingerprint = QuadSynopsisPersistence.writeWithFingerprint(destination, snapshot);
		byte[] streamed = destination.bytes.toByteArray();
		Path file = directory.resolve("synopsis-v8.bin");
		QuadSynopsisPersistence.write(file, snapshot);

		assertArrayEquals(Files.readAllBytes(file), streamed, "streamed and file payloads must match");
		assertArrayEquals(MessageDigest.getInstance("SHA-256").digest(streamed), fingerprint);
		assertFalse(QuadSynopsisPersistence.read(file, budget).rebuildRequired());
		assertTrue(destination.bulkWrites > 0, "buffered payload must reach the destination in batches");
		assertEquals(0, destination.singleByteWrites, "buffered payload must not be forwarded one byte at a time");
	}

	private static final class CountingOutputStream extends OutputStream {
		private final ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		private long singleByteWrites;
		private long bulkWrites;

		@Override
		public void write(int value) {
			singleByteWrites++;
			bytes.write(value);
		}

		@Override
		public void write(byte[] buffer, int offset, int length) throws IOException {
			bulkWrites++;
			bytes.write(buffer, offset, length);
		}
	}
}
